<?php $residentActive = ($penghuni['status'] ?? '') === 'aktif'; ?>
<div class="owner-page" x-data="residentDetail(<?= (int)$penghuni['id_penghuni'] ?>)">
  <header class="owner-page-header"><div><a href="<?= BASE_URL ?>/pemilik/penghuni" @click.prevent="utils.goBack($el.href)" class="owner-back-link"><?= masterIconSvg('chevron-left','h-4 w-4') ?> Kembali</a><h1 class="owner-title"><?= htmlspecialchars($penghuni['nama']) ?></h1><p class="owner-subtitle"><?= htmlspecialchars($penghuni['nama_kos']) ?> · Kamar <?= htmlspecialchars($penghuni['nomor_kamar']) ?></p></div><span class="rounded-full bg-primary-soft px-3 py-2 text-sm text-primary"><?= $residentActive ? 'Penghuni aktif' : 'Riwayat masa tinggal' ?></span></header>
  <section class="owner-panel"><h2 class="font-bold">Masa tinggal</h2><dl class="mt-3 grid gap-4 sm:grid-cols-3"><div><dt class="text-sm text-slate-500">Nomor HP</dt><dd><?= htmlspecialchars($penghuni['no_hp'] ?? '-') ?></dd></div><div><dt class="text-sm text-slate-500">Tanggal masuk</dt><dd><?= htmlspecialchars($penghuni['tanggal_masuk'] ?? '-') ?></dd></div><?php if (!$residentActive): ?><div><dt class="text-sm text-slate-500">Tanggal keluar</dt><dd><?= htmlspecialchars($penghuni['tanggal_keluar'] ?? '-') ?></dd></div><?php endif; ?></dl>
    <div class="ui-actions" x-data="uiActionMenu()" @betakos:close-menus.window="closeMenu(false)" @resize.window="closeMenu()">
<button type="button" x-ref="menuTrigger" class="ui-more-trigger" aria-haspopup="dialog" :aria-expanded="menuOpen" @click="menuOpen ? closeMenu() : showMenu()"><?= masterIconSvg('ellipsis','h-5 w-5') ?> Data &amp; tindakan</button>
<template x-teleport="body"><div x-show="menuOpen" x-cloak class="ui-menu-layer" @keydown.escape.stop.prevent="closeMenu()">
<div class="ui-menu-backdrop" @click="closeMenu()"></div>
<div x-ref="menuPanel" role="dialog" aria-modal="true" aria-label="Tindakan lanjutan" class="ui-action-menu" :style="menuPosition" @click="if ($event.target.closest('a,button')) closeMenu(false)"><div class="flex flex-wrap gap-2 pb-2"><?php if ($residentActive): ?><a href="<?= BASE_URL ?>/pemilik/penghuni/edit?id_penghuni=<?= (int)$penghuni['id_penghuni'] ?>" class="btn-secondary">Edit identitas</a><a href="<?= BASE_URL ?>/pemilik/kamar/detail?id_kamar=<?= (int)$penghuni['id_kamar'] ?>" class="btn-secondary">Buka kamar</a><a href="<?= BASE_URL ?>/pemilik/penghuni" class="btn-secondary">Kelola penghuni keluar</a><?php endif; ?><a href="<?= BASE_URL ?>/pemilik/riwayat?tab=keuangan&id_penghuni=<?= (int)$penghuni['id_penghuni'] ?>" class="btn-secondary">Riwayat pembayaran</a></div></div>
</div></template></div>
  </section>
  <section id="tagihan" data-help="help-resident-bills"><h2 class="text-lg font-bold">Tagihan &amp; pembayaran</h2><p class="mt-1 text-sm text-slate-500">Tagihan kamar yang terhubung dengan masa tinggal ini. Nominal bukan pembagian utang pribadi.</p>
    <div class="owner-segmented mt-3"><button type="button" @click="group='aktif'" :class="group==='aktif'?'is-active':''">Perlu ditagih</button><button type="button" @click="group='terjadwal'" :class="group==='terjadwal'?'is-active':''">Berjalan &amp; mendatang</button><button type="button" @click="group='riwayat'" :class="group==='riwayat'?'is-active':''">Riwayat</button></div>
    <p class="mt-3" x-show="loading">Memuat tagihan…</p><p x-show="error" x-text="error" role="alert" class="mt-3 text-red-700"></p><p x-show="!loading&&!error&&!filtered.length" x-cloak class="owner-empty mt-3">Tidak ada tagihan pada kelompok ini.</p>
    <div class="mt-3 grid gap-3 lg:grid-cols-2"><template x-for="bill in filtered" :key="bill.id_tagihan"><article class="owner-panel"><p class="text-sm font-semibold" x-text="date(bill.tanggal_mulai)+' – '+date(bill.tanggal_selesai)"></p><p class="mt-3 text-xs text-slate-500" x-text="group === 'riwayat' ? 'Total biaya tagihan' : 'Sisa pembayaran'"></p><p class="mt-1 text-xl font-bold" x-text="utils.formatRupiah(group === 'riwayat' ? bill.total_tagihan : bill.sisa_tagihan)"></p><span class="mt-2 inline-flex rounded-full px-2.5 py-1 text-xs font-semibold" :class="bill.status === 'lunas' ? 'bg-emerald-50 text-emerald-700' : bill.status === 'dibatalkan' ? 'bg-slate-100 text-slate-600' : 'bg-amber-50 text-amber-700'" x-text="bill.status === 'lunas' ? 'Lunas' : bill.status === 'dibatalkan' ? 'Dibatalkan' : bill.status === 'sebagian' ? 'Dibayar sebagian' : 'Belum lunas'"></span><a :href="BASE_URL+'/pemilik/pembayaran/detail?id_tagihan='+bill.id_tagihan" class="btn-secondary mt-3">Lihat pembayaran</a></article></template></div>
  </section>
</div>
<script>
function residentDetail(id){return{items:[],loading:true,error:'',group:'<?= $residentActive ? 'aktif' : 'riwayat' ?>',get filtered(){return this.items.filter(b=>{const closed=['lunas','dibatalkan'].includes(b.status);const due=[true,1,'1'].includes(b.perlu_tindakan);return this.group==='riwayat'?closed:!closed&&(this.group==='aktif'?due:!due)})},date(v){return v?new Date(v+'T00:00:00').toLocaleDateString('id-ID',{day:'numeric',month:'short',year:'numeric'}):'-'},async init(){try{const r=await API.get('/pemilik/tagihan?id_penghuni='+id,false);this.items=r.data||[]}catch(e){this.error='Tagihan belum dapat dimuat. Silakan muat ulang.'}finally{this.loading=false}}}}
</script>

